class Solution:
    def getSmallestString(self, s: str, k: int) -> str:
        res = []
        for ch in s:
            c = ord(ch) - 97
            d = min(c, 26 - c)
            if d <= k:
                k -= d
                res.append('a')
            else:
                res.append(chr(c - k + 97))
                k = 0
        return ''.join(res)

