class Solution:
    def getSmallestString(self, s: str, k: int) -> str:
        n = len(s)
        d = lambda c: min(c, 26 - c)
        suf = [0] * (n + 1)
        for i in range(n - 1, -1, -1):
            suf[i] = suf[i + 1] + d(ord(s[i]) - 97)
        res = []
        rem = k
        for i, ch in enumerate(s):
            c = ord(ch) - 97
            for t in range(26):
                dd = min(abs(c - t), 26 - abs(c - t))
                if dd <= rem - suf[i + 1]:
                    res.append(chr(97 + t))
                    rem -= dd
                    break
        return ''.join(res)

