        vector<int> suf(n + 1, 0);
        for (int i = n - 1; i >= 0; i--) suf[i] = suf[i + 1] + d(s[i] - 'a');
        string res;
        int rem = k;
        for (int i = 0; i < n; i++) {
            int c = s[i] - 'a';
            for (int t = 0; t < 26; t++) {
                int dd = min(abs(c - t), 26 - abs(c - t));
                if (dd <= rem - suf[i + 1]) { res += char('a' + t); rem -= dd; break; }
            }
        }
        return res;
    }
};

