class Solution {
    public String getSmallestString(String s, int k) {
        int n = s.length();
        int[] suf = new int[n + 1];
        for (int i = n - 1; i >= 0; i--) {
            int c = s.charAt(i) - 'a';
            suf[i] = suf[i + 1] + Math.min(c, 26 - c);
        }
        StringBuilder res = new StringBuilder();
        int rem = k;
        for (int i = 0; i < n; i++) {
            int c = s.charAt(i) - 'a';
            for (int t = 0; t < 26; t++) {
                int dd = Math.min(Math.abs(c - t), 26 - Math.abs(c - t));
                if (dd <= rem - suf[i + 1]) { res.append((char) ('a' + t)); rem -= dd; break; }
            }
        }
        return res.toString();
    }
}

